"use strict";
const log = [];
class Link {
  constructor(name) {
    this.name = name;
    this.next = null;
  }
}
exports.Link = Link;
exports.makeBox = () => ({ n: 1, label: "box", inner: { deep: true }, list: [1, 2] });
exports.makeAny = () => ({ a: 1, b: [true, null, "s", undefined], c: { d: undefined, e: 2 } });
exports.makeDoc = () => ({
  title: "doc",
  when: new Date(0),
  tags: ["a", "b"],
  nested: { ok: true, skip: undefined },
  fn() {},
});
exports.makeList = () => [{ id: 1 }, { id: 2 }];
exports.makeRedacted = () => ({
  secret: "s",
  toJSON(key) {
    log.push("toJSON:" + key);
    return { redacted: true, key };
  },
});
exports.makeCycle = () => {
  const o = { self: null };
  o.self = o;
  return o;
};
exports.makeRing = () => {
  const a = new Link("a");
  const b = new Link("b");
  a.next = b;
  b.next = a;
  return a;
};
exports.makeBoxed = () => ({
  num: new Number(1.5),
  str: new String("s\n"),
  yes: new Boolean(true),
  list: [new Number(2), Symbol("x"), () => 1],
  get computed() {
    log.push("getter");
    return 7;
  },
});
exports.makeRaw = () => ({ big: JSON.rawJSON("12345678901234567890"), plain: 1 });
exports.makeKeys = () => ["label", "n", "missing"];
// Two boxed keys that name one property, a boxed Number, a boolean that is
// not a key, and a plain name.
exports.makeKeyList = () => [new String("label"), new Number(1), new String("label"), false, "n"];
exports.makeOrdered = () => ({ b: 1, 2: 2, a: 3, 1: 4 });
exports.hold = (value) => ({ held: value, label: "h" });
exports.upper = (key, value) => {
  log.push("replacer:" + key);
  return typeof value === "string" ? value.toUpperCase() : value;
};
exports.seen = () => log.splice(0).join(",");
exports.makeOdd = () => ({
  sym: [Symbol("x")],
  map: new Map([[1, 2]]),
  set: new Set([1]),
  holes: [1, , 3],
  nan: NaN,
  negative: -0,
  nothing: null,
});
